class TestCliCommands(unittest.TestCase):
    CLI = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "cli.py")

    def _run(self, *args):
        proc = subprocess.run([sys.executable, self.CLI, *args],
                              capture_output=True, text=True)
        return proc.returncode, proc.stdout

    def test_discount_prints_the_reduced_price(self):
        code, out = self._run("discount", "10", "50")
        self.assertEqual(code, 0)
        self.assertEqual(out.strip(), "5.0")

    def test_unknown_command_exits_two(self):
        code, out = self._run("bogus")
        self.assertEqual(code, 2)
        self.assertIn("unknown command", out)


class TestCliInProcess(unittest.TestCase):
    def _call(self, argv):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            code = cli.main(argv)
        return code, buf.getvalue()

    def test_discount_returns_zero_and_prints_the_price(self):
        code, out = self._call(["discount", "10", "50"])
        self.assertEqual(code, 0)
        self.assertEqual(out.strip(), "5.0")

    def test_export_returns_zero_and_writes_the_header(self):
        code, out = self._call(["export"])
        self.assertEqual(code, 0)
        self.assertIn("name,amount", out)

    def test_unknown_command_returns_two(self):
        code, out = self._call(["bogus"])
        self.assertEqual(code, 2)
        self.assertIn("unknown command", out)

    def test_no_argv_returns_two_with_usage(self):
        code, out = self._call([])
        self.assertEqual(code, 2)
        self.assertIn("usage", out)
